import os
from pathlib import Path

import pytest


def read_note(name: str) -> str:
    """Return the UTF-8 text of the file `name` inside the `notes` directory.

    `notes` is resolved relative to the current working directory, and `name`
    is untrusted. Names that resolve to a file inside `notes` (including in
    its subdirectories, e.g. "sub/a.txt" or "sub/../a.txt") are read.
    Any name that would reach outside `notes` returns "". Examples are
    "..", "../x", absolute paths, names with NUL bytes, and symlinks that
    point outside. A missing file, a directory, an undecodable file, an
    unreadable file, or a missing `notes` directory also returns "".
    The function never raises for such inputs.
    """
    try:
        if "\0" in name:
            return ""
        if Path(name).anchor:
            return ""
        base = Path("notes").resolve()
        candidate = (base / name).resolve()
        if candidate == base or not candidate.is_relative_to(base):
            return ""
        return candidate.read_text(encoding="utf-8")
    except (OSError, ValueError, RuntimeError):
        return ""


@pytest.fixture
def workdir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    (tmp_path / "notes").mkdir()
    (tmp_path / "secret.txt").write_text("TOP SECRET", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_existing_file(workdir: Path) -> None:
    (workdir / "notes" / "a.txt").write_text("hello", encoding="utf-8")
    assert read_note("a.txt") == "hello"


def test_reads_non_ascii(workdir: Path) -> None:
    (workdir / "notes" / "u.txt").write_text("héllo ✓", encoding="utf-8")
    assert read_note("u.txt") == "héllo ✓"


def test_missing_file_gives_empty(workdir: Path) -> None:
    assert read_note("nope.txt") == ""


def test_missing_notes_dir_gives_empty(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    assert read_note("a.txt") == ""


@pytest.mark.parametrize("name", ["", ".", "..", "sub", "./"])
def test_non_file_names_give_empty(workdir: Path, name: str) -> None:
    (workdir / "notes" / "sub").mkdir()
    assert read_note(name) == ""


def test_directory_gives_empty(workdir: Path) -> None:
    (workdir / "notes" / "d.txt").mkdir()
    assert read_note("d.txt") == ""


def test_subdirectory_file_is_readable(workdir: Path) -> None:
    sub = workdir / "notes" / "sub"
    sub.mkdir()
    (sub / "b.txt").write_text("nested", encoding="utf-8")
    assert read_note("sub/b.txt") == "nested"


def test_traversal_that_stays_inside_is_readable(workdir: Path) -> None:
    (workdir / "notes" / "sub").mkdir()
    (workdir / "notes" / "a.txt").write_text("hello", encoding="utf-8")
    assert read_note("sub/../a.txt") == "hello"


@pytest.mark.parametrize(
    "name",
    [
        "../secret.txt",
        "../../secret.txt",
        "./../secret.txt",
        "sub/../../secret.txt",
        "sub/../../notes/../secret.txt",
        "..//secret.txt",
        "../notes/../secret.txt",
        "....//secret.txt",
        "..%2fsecret.txt",
        "/secret.txt",
        "//secret.txt",
    ],
)
def test_traversal_names_give_empty(workdir: Path, name: str) -> None:
    (workdir / "notes" / "sub").mkdir()
    assert read_note(name) == ""


def test_absolute_path_outside_gives_empty(workdir: Path) -> None:
    assert read_note(str(workdir / "secret.txt")) == ""


def test_sibling_directory_with_same_prefix_gives_empty(workdir: Path) -> None:
    other = workdir / "notes2"
    other.mkdir()
    (other / "x.txt").write_text("leak", encoding="utf-8")
    assert read_note("../notes2/x.txt") == ""


def test_nul_byte_gives_empty(workdir: Path) -> None:
    (workdir / "notes" / "a.txt").write_text("hello", encoding="utf-8")
    assert read_note("a.txt\0../../secret.txt") == ""
    assert read_note("a\0.txt") == ""


def test_symlink_file_escaping_gives_empty(workdir: Path) -> None:
    link = workdir / "notes" / "link.txt"
    try:
        link.symlink_to(workdir / "secret.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_note("link.txt") == ""


def test_symlink_dir_escaping_gives_empty(workdir: Path) -> None:
    outside = workdir / "outside"
    outside.mkdir()
    (outside / "x.txt").write_text("leak", encoding="utf-8")
    link = workdir / "notes" / "dirlink"
    try:
        link.symlink_to(outside, target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_note("dirlink/x.txt") == ""


def test_symlink_staying_inside_is_readable(workdir: Path) -> None:
    (workdir / "notes" / "a.txt").write_text("hello", encoding="utf-8")
    link = workdir / "notes" / "alias.txt"
    try:
        link.symlink_to(workdir / "notes" / "a.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_note("alias.txt") == "hello"


def test_undecodable_file_gives_empty(workdir: Path) -> None:
    (workdir / "notes" / "bin.dat").write_bytes(b"\xff\xfe\x00\xff")
    assert read_note("bin.dat") == ""


def test_unreadable_file_gives_empty(workdir: Path) -> None:
    p = workdir / "notes" / "locked.txt"
    p.write_text("x", encoding="utf-8")
    p.chmod(0)
    try:
        if os.access(p, os.R_OK):
            pytest.skip("permissions not enforced (e.g. running as root)")
        assert read_note("locked.txt") == ""
    finally:
        p.chmod(0o600)


def test_very_long_name_gives_empty(workdir: Path) -> None:
    assert read_note("a" * 10000) == ""
